CREATE TABLE entity_profile_review(id bigserial PRIMARY KEY,profile_id uuid NOT NULL REFERENCES entity_profile_version(id),decision text NOT NULL CHECK(decision IN('VERIFIED','CONFLICT','EXPIRED','REJECTED')),reason text NOT NULL,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE security_profile_version ADD COLUMN excerpt text NOT NULL;
ALTER TABLE security_profile_version ADD CONSTRAINT security_time_range CHECK(identifier_valid_to IS NULL OR identifier_valid_from IS NULL OR identifier_valid_to>identifier_valid_from);
ALTER TABLE security_profile_version ADD CONSTRAINT security_listing_status CHECK(listing_status IN('UNKNOWN','LISTED','DELISTED','PENDING'));
CREATE TABLE entity_identity_review(id bigserial PRIMARY KEY,left_entity_id uuid NOT NULL REFERENCES financial_entity(id),right_entity_id uuid NOT NULL REFERENCES financial_entity(id),decision text NOT NULL CHECK(decision IN('SAME_ENTITY_CANDIDATE','DIFFERENT_ENTITY','NAME_CHANGE_CANDIDATE')),evidence_id uuid NOT NULL REFERENCES raw_evidence(id),excerpt text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(left_entity_id<>right_entity_id));
-- Identity review never merges or deletes historical entities or reused security identifiers.
CREATE FUNCTION entity_profile_review_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.decision='VERIFIED' AND NOT EXISTS(SELECT 1 FROM entity_profile_version p JOIN raw_evidence r ON r.id=p.evidence_id JOIN source_registry s ON s.id=r.source_id JOIN source_license l ON l.source_id=s.id WHERE p.id=NEW.profile_id AND s.level='L0' AND l.status='APPROVED' AND l.storage_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND r.raw_content_hash=encode(sha256(r.raw_content),'hex') AND position(p.excerpt IN convert_from(r.raw_content,'UTF8'))>0 AND position(p.original_name IN p.excerpt)>0 AND (p.legal_name IS NULL OR position(p.legal_name IN p.excerpt)>0) AND (p.official_identifier IS NULL OR position(p.official_identifier IN p.excerpt)>0)) THEN RAISE EXCEPTION 'Entity identity review requires intact licensed official proof';END IF;RETURN NEW;END $$;
CREATE TRIGGER entity_profile_review_proof BEFORE INSERT ON entity_profile_review FOR EACH ROW EXECUTE FUNCTION entity_profile_review_guard();
